def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    def comp():
        st=[];cells=[]
        s=None
        # find start: first cell True not seen
        for i in range(H):
            for j in range(W):
                if g[i][j] and not seen[i][j]:
                    seen[i][j]=True;s=(i,j);st.append(s);break
            if s is not None: break
        while st:
            r,c=st.pop();cells.append((r,c))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc] and not seen[nr][nc]:
                    seen[nr][nc]=True;st.append((nr,nc))
        return cells,g[s][0]
    comps=[]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                cs,cg=comp()
                comps.append((cs,cg));seen=[[False]*W for _ in range(H)]
                for cell in cs: seen[cell[0]][cell[1]]=True
    res=[r[:] for r in g]
    for cs,c in comps:
        rs=[r for r,cc in cs];cnt=len(cs)
        cr=max(rs),max(cc),min(rs),min(cc)
        h_=cr[1]-cr[2]+1; w_=cr[0]-cr[1]+1
        if cnt==h_*w_ and h_==2 and w_==2: continue
        r0,r1,c0,c1=min(rs),max(rs),min(cc),max(cc)
        # core: cells within overlapping region of a 2x2 anchored somewhere
        best=None
        for a in range(r0,r1-h_+2):
            for b in range(c0,c1-w_+2):
                k=sum(1 for (rr,cc2) in cs if a<=rr<a+h_ and b<=cc2<b+w_)
                if best is None or k>best[0]: best=(k,a,b)
        a,b=best[1],best[2]
        for rr in range(a,a+2):
            for cc2 in range(b,b+2):
                res[rr][cc2]=c
        for (rr,cc2) in cs:
            if rr>=a and rr<a+2 and cc2>=b and cc2<b+2: pass
    return res
