def cluster_sizes(g):
    g=np.array(g); H,W=g.shape; cnt=Counter(g.ravel()); bkg=cnt.most_common(1)[0][0]
    vis=np.zeros_like(g,bool)
    sizes=[]
    for i in range(H):
        for j in range(W):
            c=int(g[i,j])
            if c!=bkg and not vis[i,j]:
                # flood fill 4-connected on same color
                st=[(i,j)]; seen={(i,j)}; size=0
                while st:
